// ═══ WHY wait() MUST release the lock ═══
// Without lock release, wait/notify would deadlock:

// Thread-A (consumer):
synchronized (lock) {
    while (queue.isEmpty()) {
        lock.wait();  // If wait() didn't release lock → Thread-B can't enter!
    }
    process(queue.poll());
}

// Thread-B (producer):
synchronized (lock) {  // NEEDS the lock to add to queue and notify!
    queue.add(item);
    lock.notify();     // wakes Thread-A
}
// If wait() held the lock: Thread-B BLOCKED at synchronized(lock) forever!
// Thread-A waiting for notify, Thread-B waiting for lock → DEADLOCK!
// wait() releasing the lock breaks this deadlock.

// ═══ WHY sleep() does NOT release the lock ═══
// sleep() is a SIMPLE DELAY — it has no communication intent.
// It doesn't know or care about locks.
// If you need a timed wait that releases the lock: use wait(millis) or Condition.await(time)

// ═══ THE PERFORMANCE BUG ═══
synchronized (accountLock) {
    // Debit the account
    account.debit(amount);

    // "Wait for the batch to settle"
    Thread.sleep(5000);  // HOLDS accountLock for 5 SECONDS!

    // Continue processing
    account.updateStatus("SETTLED");
}
// For 5 seconds: NO other thread can debit, credit, or read this account!
// 200 threads all waiting for one account lock → throughput drops to near-zero!

// ═══ FIX: use wait() or move sleep outside synchronized ═══
// Option 1: wait with timeout (releases lock!)
synchronized (accountLock) {
    account.debit(amount);
    while (!batchSettled) {
        accountLock.wait(5000);  // releases lock! Others can proceed!
    }
    account.updateStatus("SETTLED");
}

// Option 2: move sleep outside synchronized
synchronized (accountLock) {
    account.debit(amount);
}
Thread.sleep(5000);  // sleep OUTSIDE sync — lock not held!
synchronized (accountLock) {
    account.updateStatus("SETTLED");
}
