package com.bank.lockrelease;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class LockReleaseTest {

    // ═══ PROOF: wait() releases lock — another thread enters ═══
    @Test
    void wait_releasesLock_otherThreadEnters() throws InterruptedException {
        Object lock = new Object();
        boolean[] otherEntered = {false};
        CountDownLatch inWait = new CountDownLatch(1);

        Thread waiter = new Thread(() -> {
            synchronized (lock) {
                inWait.countDown();
                try { lock.wait(3000); } catch (InterruptedException e) { }
            }
        });
        waiter.start();
        inWait.await();
        Thread.sleep(50);

        // Lock released by wait() — we CAN enter!
        long start = System.currentTimeMillis();
        synchronized (lock) {
            otherEntered[0] = true;
            lock.notify();
        }
        long elapsed = System.currentTimeMillis() - start;

        waiter.join();
        assertThat(otherEntered[0]).isTrue();
        assertThat(elapsed).isLessThan(100);  // entered INSTANTLY — lock was free!
    }

    // ═══ PROOF: sleep() does NOT release lock — other thread BLOCKED ═══
    @Test
    void sleep_keepsLock_otherThreadBlocked() throws InterruptedException {
        Object lock = new Object();
        CountDownLatch inSleep = new CountDownLatch(1);

        Thread sleeper = new Thread(() -> {
            synchronized (lock) {
                inSleep.countDown();
                try { Thread.sleep(500); } catch (InterruptedException e) { }
            }
        });
        sleeper.start();
        inSleep.await();
        Thread.sleep(50);

        // Lock NOT released by sleep() — we are BLOCKED!
        long start = System.currentTimeMillis();
        synchronized (lock) {
            // reached only after sleeper wakes up!
        }
        long elapsed = System.currentTimeMillis() - start;

        sleeper.join();
        assertThat(elapsed).isGreaterThanOrEqualTo(300);  // blocked ~500ms!
    }

    // ═══ Performance impact: sleep inside sync vs outside ═══
    @Test
    void sleepInsideSync_serializes_sleepOutside_parallel() throws InterruptedException {
        Object lock = new Object();
        int threads = 5;

        // INSIDE synchronized: sequential (each waits for previous)
        long startInside = System.currentTimeMillis();
        CountDownLatch insideLatch = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                synchronized (lock) {
                    try { Thread.sleep(100); } catch (InterruptedException e) { }
                }
                insideLatch.countDown();
            }).start();
        }
        insideLatch.await();
        long insideElapsed = System.currentTimeMillis() - startInside;

        // OUTSIDE synchronized: parallel
        long startOutside = System.currentTimeMillis();
        CountDownLatch outsideLatch = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                synchronized (lock) { /* quick 1ms work */ }
                try { Thread.sleep(100); } catch (InterruptedException e) { }
                outsideLatch.countDown();
            }).start();
        }
        outsideLatch.await();
        long outsideElapsed = System.currentTimeMillis() - startOutside;

        System.out.println("Inside sync: " + insideElapsed + "ms, Outside: " + outsideElapsed + "ms");
        // Inside: ~500ms (5 × 100ms sequential). Outside: ~100ms (parallel!)
        assertThat(outsideElapsed).isLessThan(insideElapsed);
    }
}
